def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = 8
    out = [[bg] * w for _ in range(h)]
    pattern = [2, 1, 2, 2, 6]

    # Keep the original template.
    for c, v in enumerate(pattern):
        if 0 <= c + 2 < w:
            out[1][c + 2] = v

    # Each 3 marks the center of another copy of the template.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                for j, v in enumerate(pattern):
                    cc = c + j - 2
                    if 0 <= cc < w:
                        out[r][cc] = v
    return out
